contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint proposalID, uint totalWeight) public payable {
        // Set up the vault weight via an address proposal, then cancel it is not needed;
        // simply query hasMajority/hasQuorum/hasMinority on an arbitrary proposal ID.
        // For an ID never proposed, mapPID_votes[proposalID] == 0, so all thresholds fail.
        bool majority = c.hasMajority(proposalID); if (__ESBMC_reverted()) return;
        bool quorum = c.hasQuorum(proposalID); if (__ESBMC_reverted()) return;
        bool minority = c.hasMinority(proposalID); if (__ESBMC_reverted()) return;
        assert(!majority && !quorum && !minority);
    }
    receive() external payable {}
}

